/**
 * Cryptographic Utilities for Military-Grade Validation (PBKDF2)
 * Ensures plain-text codes never leave the browser.
 */

// Generate a random 4-character alphanumeric code
export function generateAttendanceCode() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // No ambiguous chars like I, 1, O, 0
    let code = '';
    const randomArray = new Uint8Array(4);
    window.crypto.getRandomValues(randomArray);
    for (let i = 0; i < 4; i++) {
        code += chars[randomArray[i] % chars.length];
    }
    return code;
}

// Convert ArrayBuffer to Hex String
function bufferToHex(buffer) {
    return Array.from(new Uint8Array(buffer))
        .map(b => b.toString(16).padStart(2, '0'))
        .join('');
}

// Convert Hex String to Uint8Array
function hexToBuffer(hex) {
    const arr = new Uint8Array(hex.length / 2);
    for (let i = 0; i < hex.length; i += 2) {
        arr[i / 2] = parseInt(hex.substring(i, i + 2), 16);
    }
    return arr;
}

// Hash a plain-text code using PBKDF2 (100,000 iterations)
export async function hashAttendanceCode(code, existingSaltHex = null) {
    const encoder = new TextEncoder();
    const keyMaterial = await window.crypto.subtle.importKey(
        'raw',
        encoder.encode(code),
        { name: 'PBKDF2' },
        false,
        ['deriveBits', 'deriveKey']
    );

    let saltBuffer;
    let saltHex;

    if (existingSaltHex) {
        saltBuffer = hexToBuffer(existingSaltHex);
        saltHex = existingSaltHex;
    } else {
        saltBuffer = window.crypto.getRandomValues(new Uint8Array(16));
        saltHex = bufferToHex(saltBuffer);
    }

    const keyBuffer = await window.crypto.subtle.deriveBits(
        {
            name: 'PBKDF2',
            salt: saltBuffer,
            iterations: 100000,
            hash: 'SHA-256'
        },
        keyMaterial,
        256
    );

    return {
        hash: bufferToHex(keyBuffer),
        salt: saltHex
    };
}

// Verify an entered code against a stored hash and salt
export async function verifyAttendanceCode(enteredCode, storedHash, storedSalt) {
    if (!enteredCode || !storedHash || !storedSalt) return false;
    
    // Hash the entered code using the exact same salt
    const result = await hashAttendanceCode(enteredCode.toUpperCase().trim(), storedSalt);
    
    // Compare the newly generated hash with the stored hash
    return result.hash === storedHash;
}
